    if max_index is not None and not isinstance(max_index, int) or max_index <= 0:
        raise ValueError("max_index must be a positive integer or None")

    fib = [0, 1]
    prime_fibs = []
    i = 2
    while True:
        fib.append(fib[-1] + fib[-2])
        if miller_rabin(fib[-1]):
            prime_fibs.append(fib[-1])
            if max_index is not None and len(prime_fibs) == max_index:
                return prime_fibs
        i += 1
        if i == n:
            return prime_fibs[-1]

